export type Song = {
  id: string;
  title: string;
  /**
   * Fixed, hand-picked official YouTube video for this song. When present it
   * is used immediately at runtime — no discovery, no API. Songs without one
   * fall back to the searchQuery-based cache generated by `npm run
   * discover-songs`.
   */
  videoId?: string | undefined;
  searchQuery: string;
};

export type Playlist = {
  id: string;
  name: string;
  subtitle: string;
  songs: Song[];
};

export type DiscoveredVideo = {
  videoId: string;
  title: string;
  thumbnailUrl: string;
};

/**
 * These are searches, not video IDs. `npm run discover-songs` is the only
 * code that sends them to YouTube Data API v3 (one-time, offline); the result
 * is cached in youtube-cache.json and served statically at runtime.
 */
